// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }
    function testFuzz_property(address victim, address caller, uint256 depositAmount, uint256 callerDeposit) public {
        vm.assume(victim != caller);
        vm.assume(victim != address(c));
        vm.assume(caller != address(c));
        vm.assume(victim != address(0));
        vm.assume(caller != address(0));
        vm.assume(depositAmount > 0);
        vm.assume(callerDeposit > 0);
        vm.assume(depositAmount < 1e40);
        vm.assume(callerDeposit < 1e40);

        vm.deal(victim, depositAmount);
        vm.prank(victim);
        (bool s, ) = address(c).call{value: depositAmount}("");
        require(s);

        vm.deal(caller, callerDeposit);
        vm.prank(caller);
        (s, ) = address(c).call{value: callerDeposit}("");
        require(s);

        uint256 balBefore = c.balances(victim);
        uint256 cBalBefore = address(c).balance;

        vm.prank(victim);
        try c.withdraw() { } catch { }

        uint256 balAfter = c.balances(victim);
        uint256 cBalAfter = address(c).balance;
        uint256 balCaller = c.balances(caller);

        assertTrue(
            balCaller <= cBalAfter
        );
    }
}
